\begin{align*}
\frac{C_1C_3}{PC_1} &= \frac{\sin(\theta_3+\theta_6)\sin(\theta_5)}{\sin(\theta_1+\theta_2)\sin(\theta_4)} = \frac{\sin(\theta_2+\theta_5)\sin(\theta_6)}{\sin(\theta_3+\theta_4)\sin(\theta_1)}
