\frac{A_1A_3}{PA_1} &= \frac{\sin(\theta_1+\theta_4)\sin(\theta_3)}{\sin(\theta_5+\theta_6)\sin(\theta_2)} = \frac{\sin(\theta_3+\theta_6)\sin(\theta_4)}{\sin(\theta_1+\theta_2)\sin(\theta_5)}
\end{align*}
Suppose all those are less than one, then the following are also less than one:
\begin{align*}
\sqrt{\frac{C_1C_3}{PC_1} \cdot \frac{B_1B_3}{PB_1}} &= \sqrt{\frac{\sin(\theta_2+\theta_5)\sin(\theta_6)}{\sin(\theta_3+\theta_4)\sin(\theta_1)}\cdot \frac{\sin(\theta_2+\theta_5)\sin(\theta_1)}{\sin(\theta_3+\theta_4)\sin(\theta_6)}} 
&= \frac{\sin(\theta_2+\theta_5)}{\sin(\theta_3+\theta_4)} 
\sqrt{\frac{B_1B_3}{PB_1} \cdot \frac{A_1A_3}{PA_1}} &= 
\sqrt{\frac{\sin(\theta_1+\theta_4)\sin(\theta_2)}{\sin(\theta_5+\theta_6)\sin(\theta_3)}\cdot \frac{\sin(\theta_1+\theta_4)\sin(\theta_3)}{\sin(\theta_5+\theta_6)\sin(\theta_2)}} 
&= \frac{\sin(\theta_1+\theta_4)}{\sin(\theta_5+\theta_6)} 
\sqrt{\frac{A_1A_3}{PA_1} \cdot \frac{C_1C_3}{PC_1}} &= 
\sqrt{\frac{\sin(\theta_3+\theta_6)\sin(\theta_4)}{\sin(\theta_1+\theta_2)\sin(\theta_5)}\cdot \frac{\sin(\theta_3+\theta_6)\sin(\theta_5)}{\sin(\theta_1+\theta_2)\sin(\theta_4)}} 
&= \frac{\sin(\theta_3+\theta_6)}{\sin(\theta_1+\theta_2)}
\end{align*}
Therefore, 
