B_1&=\left(\frac{p}{1-q},0,\frac{r}{1-q}\right)
B_1&=\left(\frac{p}{1-r},\frac{q}{1-r},0\right).
\end{align*}
Then
\begin{align*}
A_2&=2A_1-P&=\left(-p,\frac{pq+q}{1-p},\frac{pr+r}{1-p}\right)
B_2&=2B_1-P&=\left(\frac{qp+p}{1-p},-q,\frac{qr+r}{1-p}\right)
C_2&=2C_1-P&=\left(\frac{rp+p}{1-p},\frac{rq+q}{1-p},-r\right)
\end{align*}
so
\begin{align*}
\mathrm{Pow}_{(ABC)}(A_2)&=-a^2\cdot\frac{pq+q}{1-p}\cdot\frac{pr+r}{1-p}+b^2p\cdot\frac{pr+r}{1-p}+c^2p\cdot\frac{pq+q}{1-p}
&=-\frac{p+1}{(1-p)^2}\left(a^2qr(p+1)+b^2rp(p-1)+c^2pq(p-1)\right).
\end{align*}
Similarly,
\begin{align*}
\mathrm{Pow}_{(ABC)}(B_2)&=-\frac{q+1}{(1-q)^2}\left(a^2qr(q-1)+b^2rp(q+1)+c^2pq(q-1)\right)
\mathrm{Pow}_{(ABC)}(C_2)&=-\frac{r+1}{(1-r)^2}\left(a^2qr(r-1)+b^2rp(r-1)+c^2pq(r+1)\right)
\end{align*}
so
\[
\frac{(1-p)^2}{p+1}\mathrm{Pow}_{(ABC)}(A_2)+\frac{(1-q)^2}{q+1}\mathrm{Pow}_{(ABC)}(B_2)+\frac{(1-r)^2}{r+1}\mathrm{Pow}_{(ABC)}(C_2)=0
\]
(note that  $p+q+r-1=0$ ). Since  $p,q,r>0$  and thus  $\frac{(1-p)^2}{p+1},\frac{(1-q)^2}{q+1},\frac{(1-r)^2}{r+1}>0$ , it follows that at least one of  $\mathrm{Pow}_{(ABC)}(A_2),\mathrm{Pow}_{(ABC)}(B_2),\mathrm{Pow}_{(ABC)}(C_2)$  must be positive. Thus at least one of  $A_2,B_2,C_2$  is not inside  $(ABC)$ .  $\square$

