\begin{proof}
Set  $\Gamma$  as the unit circle. Then it is well known that  $h_c=-\frac{ab}{c}$  so \begin{align*}
p &= \frac{2b\left(-\frac{ab}{c}\right)}{b-\frac{ab}{c}} 
&= \frac{-\frac{2ab^2}{c}}{\frac{1}{c}(bc-ab)} 
&= \frac{2ab}{a-c}
\end{align*}
and

\begin{align*}
\frac{p-h}{a-n} + \frac{\bar{p}-\bar{h}}{\bar{a}-\bar{n}} &= \frac{\frac{2ab}{a-c}-(a+b+c)}{a-\frac{1}{2}(a+b+c)} + \frac{\frac{2c}{b(c-a)}-\left( \frac{1}{a}+\frac{1}{b}+\frac{1}{c} \right)}{\frac{1}{a}-\frac{1}{2}\left( \frac{1}{a}+\frac{1}{b}+\frac{1}{c} \right)} 
&= \frac{2}{a-c}\left( \frac{2ab-(a-c)(a+b+c)}{a-b-c} \right)+\frac{2}{c-a}\left( \frac{\frac{2c}{b}-(c-a)\left( \frac{1}{a}+\frac{1}{b}+\frac{1}{c} \right)}{\frac{1}{a}-\frac{1}{b}-\frac{1}{c}} \right) 
&= \frac{2}{a-c}\left( \frac{2ab-b(a-c)+(a-c)(a+c)}{a-b-c}-\frac{\frac{2c}{b}-\frac{1}{b}(c-a)-(c-a)\left( \frac{1}{a}+\frac{1}{c} \right)}{\frac{1}{a}-\frac{1}{b}-\frac{1}{c}} \right) 
&= \frac{2}{a-c}\left( \frac{b(a+c)+(a-c)(a+c)}{a-b-c}-\frac{\frac{1}{b}(a+c)-\left( \frac{1}{a}-\frac{1}{c} \right)(a+c)}{\frac{1}{a}-\frac{1}{b}-\frac{1}{c}} \right) 
