Barycentric coordinates on  $\triangle ABC$ . Let  $S:=2[ABC]$ . Let  $D=:(t,\,1-t,\,0)$  and  $d^2:=CD^2=a^2(1-t)+b^2t-c^2t(1-t)$ . Then
\[
X=\left(t:1-t:-\frac{c^2t(1-t)}{a^2(1-t)+b^2t}\right)=\left(\frac{t(a^2(1-t)+b^2t)}{d^2},\,\frac{(1-t)(a^2(1-t)+b^2t)}{d^2},\,-\frac{c^2t(1-t)}{d^2}\right).
\]
Note that  $\triangle XAD\sim\triangle BCD$ . Let  $P$  be the circumcenter of  $\triangle BCD$ . Since  $CD=d$ ,  $BD=ct$ ,  $BC=a$ , and  $2[BCD]=tS$ , we have
\begin{align*}
P&=\frac{d^2(a^2+c^2t^2-d^2)}{4t^2S^2}B+\frac{c^2t^2(a^2+d^2-c^2t^2)}{4t^2S^2}C+\frac{a^2(d^2+c^2t^2-a^2)}{4t^2S^2}D
&=\frac{d^2(a^2t-b^2t+c^2t)}{4t^2S^2}B+\frac{c^2t^2(2a^2-a^2t+b^2t-c^2t)}{4t^2S^2}C+\frac{a^2(2c^2t^2-a^2t+b^2t-c^2t)}{4t^2S^2}D
&=\frac{d^2S_B}{2tS^2}B+\frac{c^2t^2(a^2-S_Bt)}{2t^2S^2}C+\frac{a^2(c^2t-S_B)}{2tS^2}D.
\end{align*}
Thus
\[
O_1=\frac{d^2S_B}{2tS^2}X+\frac{c^2t^2(a^2-S_Bt)}{2t^2S^2}A+\frac{a^2(c^2t-S_B)}{2tS^2}D.
\]
The first coordinate is
\begin{align*}
\frac{d^2S_B}{2tS^2}\cdot\frac{t(a^2(1-t)+b^2t)}{d^2}+\frac{c^2t^2(a^2-S_Bt)}{2t^2S^2}+\frac{a^2(c^2t-S_B)}{2tS^2}\cdot t&=\frac{S_B(a^2(1-t)+b^2t)+c^2(a^2-S_Bt)+a^2(c^2t-S_B)}{2S^2}
&=\frac{a^2c^2(1+t)-2S_B^2t}{2S^2}
&=\frac{2S^2t+a^2c^2(1-t)}{2S^2},
\end{align*}
the second coordinate is
\begin{align*}
\frac{d^2S_B}{2tS^2}\cdot\frac{(1-t)(a^2(1-t)+b^2t)}{d^2}+\frac{a^2(c^2t-S_B)}{2tS^2}(1-t)&=\frac{(1-t)(S_B(a^2(1-t)+b^2t)+a^2(c^2t-S_B))}{2tS^2}
&=\frac{(1-t)(a^2S_A+b^2S_B)}{2S^2}
&=\frac{(1-t)(2S^2-c^2S_C)}{2S^2},
\end{align*}
and the third coordinate is
\[
\frac{d^2S_B}{2tS^2}\left(-\frac{c^2t(1-t)}{d^2}\right)=-\frac{c^2S_B(1-t)}{2S^2}.
\]
Thus
\begin{align*}
O_1&=\left(\frac{2S^2t+a^2c^2(1-t)}{2S^2},\,\frac{(1-t)(2S^2-c^2S_C)}{2S^2},\,-\frac{c^2S_B(1-t)}{2S^2}\right)
O_2&=\left(\frac{t(2S^2-c^2S_C)}{2S^2},\,\frac{2S^2(1-t)+b^2c^2t}{2S^2},\,-\frac{c^2S_At}{2S^2}\right).
\end{align*}
Suppose  $A,\,B,\,C$  are in counterclockwise order. Then  $O,\,O_1,\,O_2$  are also in counterclockwise order, so
\begin{align*}
\frac{[OO_1O_2]}{[ABC]}=\frac{c^2}{8S^6}\begin{vmatrix}
a^2S_A & b^2S_B & S_C
2S^2t+a^2c^2(1-t) & (1-t)(2S^2-c^2S_C) & -S_B(1-t)
t(2S^2-c^2S_C) & 2S^2(1-t)+b^2c^2t & -S_At
\end{vmatrix}.
\end{align*}
It suffices to minimize
\begin{align*}
a^2S_A\left(-S_At(1-t)(2S^2-c^2S_C)+S_B(1-t)(2S^2(1-t)+b^2c^2t)\right)-b^2S_B\left(-S_At(2S^2t+a^2c^2(1-t))+S_Bt(1-t)(2S^2-c^2S_C)\right)+S_C\left((2S^2t+a^2c^2(1-t))(2S^2(1-t)+b^2c^2t)-t(1-t)(2S^2-c^2S_C)^2\right).
