&=c^2S^2(a^2S_A+b^2S_B)+c^2S_C\left(2S^2(a^2+b^2)-4S_CS^2-c^2S^2\right)
&=c^2S^2(a^2S_A+b^2S_B+c^2S_C)
&=2c^2S^4
\end{align*}
and the coefficient of  $t$  is
\begin{align*}
&\quad\ \,a^2S_A\left(-S_A(2S^2-c^2S_C)+S_B(-2S^2+b^2c^2-2S^2)\right)-b^2S_B\left(-a^2c^2S_A+S_B(2S^2-c^2S_C)\right)+S_C\left(2S^2(2S^2-a^2c^2)+a^2c^2(b^2c^2-2S^2)-(2S^2-c^2S_C)^2\right)
