[asy]
size(7cm);
import geometry;

point O=(-3,1);
point P_1=(3,1);
point Q_2=(-8,7);
circle C_1=circle(O,length(segment(O,P_1)));
circle C_2=circle(O,length(segment(O,Q_2)));
point P_2=intersectionpoints(C_1,P_1--Q_2)[1];
circle omega=circle(O,Q_2,P_1);
point Q_1=intersectionpoints(C_2,omega)[0];
point X=intersectionpoints(bisector(Q_1,Q_2),omega)[1];

draw(C_1); 
draw(C_2); 
draw(omega,dotted); 
draw(P_1--Q_2); 
draw(Q_1--X--Q_2); 
draw(X--O); 
draw(O--P_1--Q_1); 
draw(O--Q_2);

dot(O^^P_1^^Q_2^^P_2^^Q_1^^X);

label(" $O$ ",O,SW); 
label(" $P_1$ ",P_1,SW); 
label(" $Q_2$ ",Q_2,NW); 
label(" $P_2$ ",P_2,N); 
label(" $Q_1$ ",Q_1,SE); 
label(" $X$ ",X,NE);
label(" $\mathcal{C}_1$ ",(-7,-3),N);
label(" $\mathcal{C}_2$ ",(-6.5,-6),N);
[/asy]
Let  $O$  be the center of circles  $\mathcal{C}_1$  and  $\mathcal{C}_2.$  Since  $\angle OQ_{\{1,2\}}X=\angle OP_1X=90,$  we know  $OP_1Q_1XQ_2$  is cyclic. Hence,   $$ \angle Q_1P_1X=\tfrac{1}{2}\widehat{XQ_1}=\tfrac{1}{2}\widehat{XQ_2}=\angle XP_1Q_2. $$    $\square$

